//
// closure
//
(function() {
    //
    // module globals
    //
    var mod = {}
    //
    // name
    //
    var name = 'image invert'
    //
    // initialization
    //
    var init = function() { }
    //
    // inputs
    //
    var inputs = {
        image: {
            type: 'RGBA',
            event: function(evt) {
                mod.input = evt.detail
                var ctx = mod.img.getContext("2d")
                ctx.canvas.width = mod.input.width
                ctx.canvas.height = mod.input.height
                ctx.putImageData(mod.input, 0, 0)
                image_invert()
            }
        }
    }
    //
    // outputs
    //
    var outputs = {
        image: {
            type: 'RGBA',
            event: function() {
                var ctx = mod.img.getContext("2d")
                var img = ctx.getImageData(0,0,mod.img.width,mod.img.height)
                mods.output(mod,'image',img)
            }
        }
    }
    //
    // interface
    //
    var interface = function(div) {
        mod.div = div
        //
        // on-screen drawing canvas
        //
        var canvas = document.createElement('canvas')
        canvas.width = mods.ui.canvas
        canvas.height = mods.ui.canvas
        canvas.style.backgroundColor = 'rgb(255,255,255)'
        div.appendChild(canvas)
        mod.canvas = canvas
        div.appendChild(document.createElement('br'))
        //
        // off-screen image canvas
        //
        var canvas = document.createElement('canvas')
        mod.img = canvas
        //
        // view button
        //
        var btn = document.createElement('button')
        btn.style.padding = mods.ui.padding
        btn.style.margin = 1
        btn.appendChild(document.createTextNode('view'))
        btn.addEventListener('click', function() {
            var win = window.open('')
            var btn = document.createElement('button')
            btn.appendChild(document.createTextNode('close'))
            btn.style.padding = mods.ui.padding
            btn.style.margin = 1
            btn.addEventListener('click', function() {
                win.close()
            })
            win.document.body.appendChild(btn)
            win.document.body.appendChild(document.createElement('br'))
            var canvas = document.createElement('canvas')
            canvas.width = mod.img.width
            canvas.height = mod.img.height
            win.document.body.appendChild(canvas)
            var ctx = canvas.getContext("2d")
            ctx.drawImage(mod.img, 0, 0)
        })
        div.appendChild(btn)
    }
    //
    // local functions
    //
    function image_invert() {
        var blob = new Blob(['(' + worker.toString() + '())'])
        var url = window.URL.createObjectURL(blob)
        var webworker = new Worker(url)
        webworker.addEventListener('message', function(evt) {
            window.URL.revokeObjectURL(url)
            var h = mod.img.height
            var w = mod.img.width
            var buf = new Uint8ClampedArray(evt.data.buffer)
            var imgdata = new ImageData(buf,w,h)
            var ctx = mod.img.getContext("2d")
            ctx.putImageData(imgdata,0,0)
            if (w > h) {
                var x0 = 0
                var y0 = mod.canvas.height * .5 * (1 - h / w)
                var wd = mod.canvas.width
                var hd = mod.canvas.width * h / w
            } else {
                var x0 = mod.canvas.width * .5 * (1 - w / h)
                var y0 = 0
                var wd = mod.canvas.height * w / h
                var hd = mod.canvas.height
            }
            var ctx = mod.canvas.getContext("2d")
            ctx.clearRect(0,0,mod.canvas.width,mod.canvas.height)
            ctx.drawImage(mod.img,x0,y0,wd,hd)
            webworker.terminate()
            outputs.image.event()
            })
        var ctx = mod.canvas.getContext("2d")
        ctx.clearRect(0, 0, mod.canvas.width, mod.canvas.height)
        var ctx = mod.img.getContext("2d")
        ctx.putImageData(mod.input,0,0)
        var img = ctx.getImageData(0,0,mod.img.width,mod.img.height)
        webworker.postMessage({
            height: mod.input.height,
            width: mod.input.width,
            buffer: img.data.buffer
            }, [img.data.buffer])

    }

    function worker() {
        self.addEventListener('message', function(evt) {
            var h = evt.data.height
            var w = evt.data.width
            var buf = new Uint8ClampedArray(evt.data.buffer)

            for (var row = 0; row < h; ++row) {
                for (var col = 0; col < w; ++col) {
                    buf[(h-1-row)*w*4+col*4+0] = 255 - buf[(h-1-row)*w*4+col*4+0]
                    buf[(h-1-row)*w*4+col*4+1] = 255 - buf[(h-1-row)*w*4+col*4+1]
                    buf[(h-1-row)*w*4+col*4+2] = 255 - buf[(h-1-row)*w*4+col*4+2]
                    buf[(h-1-row)*w*4+col*4+3] = buf[(h-1-row)*w*4+col*4+3]
                }
            }
            self.postMessage({
                buffer: buf.buffer
            }, [buf.buffer])
        })
    }
    //
    // return values
    //
    return ({
        mod: mod,
        name: name,
        init: init,
        inputs: inputs,
        outputs: outputs,
        interface: interface
    })
}())

