        })
        var canvas = mod.canvas
        var ctx = canvas.getContext("2d")
        ctx.clearRect(0, 0, canvas.width, canvas.height)
        var h = mod.img.height
        var w = mod.img.width
        var ctx = mod.img.getContext("2d")
