                         buf[(h-1-row)*w*4+col*4+2] = 255
                         buf[(h-1-row)*w*4+col*4+3] = 255
                         }
                      }
                   */
                   }
               }
            self.postMessage({
                buffer: buf.buffer
            }, [buf.buffer])
        })
    }
    //
    // return values
    //
    return ({
        mod: mod,
        name: name,
        init: init,
        inputs: inputs,
        outputs: outputs,
        interface: interface
    })
}())

