//
// mill with V Bit
//
// Sibin k s
//
// (c) Massachusetts Institute of Technology 2024
//
//



(function() {
    var mod = {}
    var name = 'V-Bit Calculator'
    var init = function() {
        mod.tool_num.value = '2'
        mod.angle.value = '30'
        mod.tip_dia.value = '0.35'
        mod.cut_depth.value = '0.09'
        mod.max_depth.value = '0.09'
        outputs.settings.event() // Initialize diagram values
    }
    var inputs = {}
    var outputs = {
        settings: {
            type: 'object',
            event: function() {
                var angle_rad = (parseFloat(mod.angle.value) / 2) * (Math.PI / 180)
                var depth = parseFloat(mod.cut_depth.value)
                var tip = parseFloat(mod.tip_dia.value)

                // Effective Diameter Calculation
                var effective_dia = tip + (2 * depth * Math.tan(angle_rad))

                // --- Update Live Values in SVG ---
                if (mod.svg_tip) mod.svg_tip.textContent = tip.toFixed(2) + "mm"
                if (mod.svg_depth) mod.svg_depth.textContent = depth.toFixed(2) + "mm"
                if (mod.svg_eff) mod.svg_eff.textContent = effective_dia.toFixed(3) + "mm"

                var obj = {
                    'tool': mod.tool_num.value,
                    'dia': effective_dia.toFixed(4),
                    'cut': depth,
                    'max': parseFloat(mod.max_depth.value)
                }
                mods.output(mod, 'settings', obj)
            }
        }
    }
    var interface = function(div) {
        mod.div = div

        // --- LIVE SVG DIAGRAM ---
        var svgNS = "http://www.w3.org/2000/svg"
        var svg = document.createElementNS(svgNS, "svg")
        svg.setAttribute('width', '160')
        svg.setAttribute('height', '110')
        svg.style.display = 'block'
        svg.style.margin = 'auto'
        svg.style.backgroundColor = '#f8f8f8'
        svg.style.border = '1px solid #ddd'

        // V-Shape Path
        var vpath = document.createElementNS(svgNS, 'path')
        vpath.setAttribute('d', 'M 30,15 L 75,85 L 85,85 L 130,15')
        vpath.setAttribute('stroke', '#333')
        vpath.setAttribute('fill', '#e0e0e0')
        vpath.setAttribute('stroke-width', '2')
        svg.appendChild(vpath)

        // Depth/Diameter Indicator Lines
        var dline = document.createElementNS(svgNS, 'line')
        dline.setAttribute('x1', '50'); dline.setAttribute('y1', '45')
        dline.setAttribute('x2', '110'); dline.setAttribute('y2', '45')
        dline.setAttribute('stroke', 'red'); dline.setAttribute('stroke-dasharray', '3')
        svg.appendChild(dline)

        // Text Elements for Live Values
        function createSvgText(x, y, color, id_var) {
            var t = document.createElementNS(svgNS, 'text')
            t.setAttribute('x', x); t.setAttribute('y', y)
            t.setAttribute('font-size', '11'); t.setAttribute('fill', color)
            t.setAttribute('font-weight', 'bold')
            t.setAttribute('text-anchor', 'middle')
            mod[id_var] = t
            svg.appendChild(t)
        }

        createSvgText(80, 100, 'black', 'svg_tip')   // Value at bottom
        createSvgText(25, 50, 'red', 'svg_depth')    // Value at side
        createSvgText(80, 40, 'blue', 'svg_eff')     // Value at dash line

        div.appendChild(svg)
        div.appendChild(document.createElement('br'))

        // --- INPUT FIELDS ---
        function createInput(label, variable) {
            div.appendChild(document.createTextNode(label))
            var i = document.createElement('input'); i.type = 'text'; i.size = 6;
            i.addEventListener('input', outputs.settings.event)
            div.appendChild(i); mod[variable] = i;
            div.appendChild(document.createElement('br'))
        }
        createInput('Tool Number: ', 'tool_num')
        createInput('V-Angle (deg): ', 'angle')
        createInput('Tip Dia (mm): ', 'tip_dia')
        createInput('Cut Depth (mm): ', 'cut_depth')
        createInput('Max Depth (mm): ', 'max_depth')

        var btn = document.createElement('button')
        btn.style.padding = mods.ui.padding
        btn.appendChild(document.createTextNode('Sync'))
        btn.addEventListener('click', outputs.settings.event)
        div.appendChild(btn)
    }
    return { mod: mod, name: name, init: init, inputs: inputs, outputs: outputs, interface: interface }
}())

